mapper.update:
UPDATE xsy_mall_home_popup
SET enabled = #{enabled}, display_rule = #{displayRule}, start_at = #{startAt}, end_at = #{endAt},
    content = CAST(#{content} AS jsonb), version = version + 1,
    updated_at = CURRENT_TIMESTAMP, updated_by = #{operator}
WHERE id = 1
    AND version = #{version}

UPDATE xsy_mall_home_draft
SET content = CAST(#{content} AS jsonb), theme_code = #{themeCode}, theme_color = #{themeColor},
    version = version + 1,
    updated_at = CURRENT_TIMESTAMP, updated_by = #{operator}
WHERE id = 1
    AND version = #{version}

UPDATE xsy_mall_home_pointer
SET current_release_id = #{releaseId}, version = version + 1, updated_at = CURRENT_TIMESTAMP,
    updated_by = #{operator}
WHERE id = 1
    AND version = #{version}
